/// <summary>
/// AVA
/// </summary>
/// <param name = "dataProvider">SrsReportDataProviderBase</param>
/// <returns>SysDocuBrandDetailsTmp</returns>
public static SysDocuBrandDetailsTmp getDocuBrandDetailsTmp(SrsReportDataProviderBase dataProvider)
{
    SysDocuBrandDetailsTmp avaTableTmp = next getDocuBrandDetailsTmp(dataProvider);

    if (dataProvider)
    {
        SysDocuBrandDetails avaTable  = SysDocuBrandDetails::getBrandDocument(dataProvider.parmDocuBrandContract());
        avaTableTmp.AVASender               = avaTable.AVASender;
        avaTableTmp.AVAImage1International  = avaTable.AVAImage1International;
        avaTableTmp.AVAImage2International  = avaTable.AVAImage2International;
        avaTableTmp.AVAImage3International  = avaTable.AVAImage3International;
    }

    return avaTableTmp;
}
